const EXMEDIA=new Map();
const exNorm=s=>String(s||"").toLowerCase().replace(/[’']/g,"").replace(/[^a-z0-9]+/g," ").trim();
const exTokens=s=>new Set(exNorm(s).split(/\s+/).filter(x=>x.length>2));
function exerciseImage(e,large=false){
  if(!e)return "";
  const hit=EXMEDIA.get(e.id)||null;
  const src=hit?.images?.[0];
  return src?`https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/${src}`:"";
}
function exerciseMediaInfo(e){
  if(!e)return null;
  if(EXMEDIA.has(e.id))return EXMEDIA.get(e.id);
  const n=exNorm(e.name?.en||"");
  let best=null,score=0;
  for(const d of EXDB){
    const dn=exNorm(d.name);
    let sc=0;
    if(dn===n)sc=1000;
    else{
      const a=exTokens(n),b=exTokens(dn); let common=0; a.forEach(t=>{if(b.has(t))common++});
      sc=common*20-Math.abs(a.size-b.size)*2;
      if(dn.includes(n)||n.includes(dn))sc+=120;
    }
    if(sc>score){score=sc;best=d}
  }
  if(best&&score>=15)EXMEDIA.set(e.id,best);
  return EXMEDIA.get(e.id)||null;
}
function exerciseImageTag(e,cls="exerciseThumb",large=false){
  const src=exerciseImage(e,large);
  if(src)return `<img class="${cls}" src="${src}" alt="${esc(e.name?.[S.lang]||e.name?.en||"")}" loading="lazy" onerror="this.style.display='none';this.nextElementSibling?.classList.remove('hidden')"><div class="exerciseFallback hidden">${exerciseGlyph()}</div>`;
  return `<div class="${cls} exercisePlaceholder">${exerciseGlyph()}</div>`;
}
