function openExerciseInfo(eid){const e=S.exercises.find(x=>x.id===eid);if(!e)return;const m=exerciseMediaInfo(e);const imgs=m?.images||[];const gallery=imgs.length>1?`<div class="exerciseGallery">${imgs.slice(0,2).map(src=>`<img src="https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/${src}" alt="${esc(e.name?.[S.lang]||e.name?.en||"")}" onerror="this.style.display='none'">`).join("")}</div>`:exerciseImageTag(e,"exerciseHero",true);const instructions=(m?.instructions||[]).slice(0,5);modal(`<div class="exerciseInfo">${gallery}<h2>${esc(e.name[S.lang])}</h2><div class="pill" style="display:inline-block;margin-bottom:10px">${esc(e.muscle[S.lang])}</div>${m?.equipment?`<div class="muted" style="margin-bottom:10px">${esc(m.equipment)}</div>`:""}${instructions.length?`<h3>${S.lang==='lt'?'Atlikimas':'How to perform'}</h3><ol>${instructions.map(x=>`<li>${esc(x)}</li>`).join("")}</ol>`:`<p class="muted">${S.lang==='lt'?'Informacija apie pratimą':'Exercise information'}</p>`}<div class="muted" style="margin-top:12px">Exercise images: Free Exercise DB · public domain</div></div>`)}
