function renderDrawer(){const el=document.getElementById("drawerList");if(!el)return;const active=document.querySelector('.view.active')?.id||'dashboard';const emojis={dashboard:"🏠",workouts:"🏋️",progress:"📈",photos:"📸",weight:"⚖️",measurements:"📏",nutrition:"🍽️",goals:"🎯",settings:"⚙️"};el.innerHTML=drawerItems.map(x=>`<button class="drawerItem ${x[0]===active?'active':''}" onclick="closeDrawer();show('${x[0]}')"><span class="drawerIcon emojiIcon">${emojis[x[0]]||"•"}</span><span>${t(x[0])}</span></button>`).join("")}
