function closeDrawer(){document.getElementById('drawer').classList.remove('show');document.getElementById('drawerShade').classList.remove('show')}
function show(id){closeDrawer();document.querySelectorAll(".view").forEach(x=>x.classList.remove("active"));if(!document.getElementById(id))id="dashboard";document.getElementById(id).classList.add("active");document.querySelectorAll(".nav button").forEach(b=>b.classList.toggle("active",b.dataset.v===id));render(id);renderDrawer()}
