function weekStartDate(){const d=new Date();d.setHours(0,0,0,0);const day=d.getDay();const diff=(day+6)%7;d.setDate(d.getDate()-diff);return d.toISOString().slice(0,10)}
function thisWeekWorkoutCount(){const start=weekStartDate();return workoutHistoryGroups().filter(g=>g.date>=start&&g.date<=today()).length}
function dashboard(){let w=last(S.weight),wk=thisWeekWorkoutCount();document.getElementById('dashboard').innerHTML=`<div class="hello">${t("hello")}</div><h1 class="title">ASFITNESS</h1><div class="grid"><div class="card"><div class="muted">${t("currentWeight")}</div><div class="big">${w?w.value+" "+t("kg"):"—"}</div></div><div class="card"><div class="muted">${t("thisWeek")}</div><div class="big">${wk}</div><div class="muted">${t("workoutsDone")}</div></div><div class="card"><div class="muted">${t("measurements")}</div><div class="big">${S.measurements.length}</div></div><div class="card"><div class="muted">${t("exerciseProgress")}</div><div class="big">${exerciseStats().filter(x=>x.first>0).length}</div></div></div><div class="card" style="margin-top:12px"><h3>${t("weightTrend")}</h3><canvas id="dc" width="800" height="250"></canvas></div>`;chart("dc",S.weight)}
function openWeight(index=null){const x=index!==null?S.weight[index]:null;modal(`<h2>${x?t("edit"):t("addWeight")}</h2><label>${t("date")}</label><input id="d" type="date" value="${x?.date||today()}"><label>${t("kg")}</label><input id="v" type="number" step=".1" value="${x?.value??""}"><div class="row" style="margin-top:15px"><button class="btn ghost" onclick="closeModal()">${t("cancel")}</button><button class="btn" onclick="saveW(${index===null?'null':index})">${t("save")}</button></div>`)}
function saveW(index){const v=+document.getElementById("v").value;if(!v)return;const o={id:index!==null&&S.weight[index]?.id||uid(),date:document.getElementById('d').value,value:v};if(index===null)S.weight.push(o);else S.weight[index]=o;S.weight.sort((a,b)=>a.date.localeCompare(b.date));save();closeModal();show("weight")}
function deleteWeight(i){if(!confirm(t("confirmDelete")))return;S.weight.splice(i,1);save();show("weight")}
function weight(){document.getElementById('weight').innerHTML=`<h1 class="title">${t("weight")}</h1><button class="btn" onclick="openWeight()">+ ${t("addWeight")}</button><div class="list" style="margin-top:12px">${S.weight.map((x,i)=>({x,i})).reverse().map(o=>`<div class="item row"><div><b>${o.x.value} ${t("kg")}</b><div class="muted">${o.x.date}</div></div><div class="actions"><button class="mini" onclick="openWeight(${o.i})">${t("edit")}</button><button class="mini danger" onclick="deleteWeight(${o.i})">${t("delete")}</button></div></div>`).join("")||`<div class="empty">${t("noData")}</div>`}</div>`}
const mf=["waist","chest","hips","thigh","arm","neck"];
function openM(index=null){const x=index!==null?S.measurements[index]:null;modal(`<h2>${x?t("edit"):t("addMeasurement")}</h2><label>${t("date")}</label><input id="md" type="date" value="${x?.date||today()}"><div class="formgrid">${mf.map(k=>`<div><label>${t(k)}</label><input id="m${k}" type="number" step=".1" value="${x?.[k]??""}"></div>`).join("")}</div><div class="row" style="margin-top:12px"><button class="btn ghost" onclick="closeModal()">${t("cancel")}</button><button class="btn" onclick="saveM(${index===null?'null':index})">${t("save")}</button></div>`)}
function saveM(index){let o={id:index!==null&&S.measurements[index]?.id||uid(),date:document.getElementById('md').value};mf.forEach(k=>o[k]=+document.getElementById("m"+k).value||null);if(index===null)S.measurements.push(o);else S.measurements[index]=o;S.measurements.sort((a,b)=>a.date.localeCompare(b.date));save();closeModal();show("measurements")}
function deleteMeasurement(i){if(!confirm(t("confirmDelete")))return;S.measurements.splice(i,1);save();show("measurements")}
function measurements(){let x=last(S.measurements)||{};document.getElementById('measurements').innerHTML=`<h1 class="title">${t("measurements")}</h1><div class="grid">${mf.map(k=>`<div class="card"><div class="muted">${t(k)}</div><div class="big">${x[k]?x[k]+" cm":"—"}</div></div>`).join("")}</div><button class="btn" style="margin:12px 0" onclick="openM()">+ ${t("addMeasurement")}</button><div class="list">${S.measurements.map((x,i)=>({x,i})).reverse().map(o=>`<div class="item"><div class="row"><b>${o.x.date}</b><div class="actions"><button class="mini" onclick="openM(${o.i})">${t("edit")}</button><button class="mini danger" onclick="deleteMeasurement(${o.i})">${t("delete")}</button></div></div><div class="muted" style="margin-top:7px">${mf.filter(k=>o.x[k]).map(k=>t(k)+" "+o.x[k]+" cm").join(" · ")}</div></div>`).join("")||`<div class="empty">${t("noData")}</div>`}</div>`}
let planDraft=null;
function planSelectedHtml(){if(!planDraft?.exerciseIds?.length)return `<div class="empty" style="padding:16px 4px">${t("noData")}</div>`;return `<div id="planDragList" class="dragList">${planDraft.exerciseIds.map((eid,i)=>{const e=S.exercises.find(x=>x.id===eid);return `<div class="dragItem" data-index="${i}"><button class="dragHandle" type="button" aria-label="${esc(t('dragHint'))}">${dragSvg()}</button>${e?exerciseImageTag(e,'exerciseMini'):''}<button class="exerciseNameBtn" type="button" onclick="openExerciseInfo('${e?.id||eid}')"><div style="flex:1;text-align:left"><b>${i+1}. ${esc(e?e.name[S.lang]:eid)}</b><div class="muted">${e?esc(e.muscle[S.lang]):""}</div></div></button><button class="mini danger" onclick="draftRemoveEx(${i})">×</button></div>`}).join("")}</div><div class="dragHint">${t("dragHint")}</div>`}
function planPickerHtml(q){q=(q||"").toLowerCase();const selected=new Set(planDraft?.exerciseIds||[]);return S.exercises.filter(e=>!q||e.name.en.toLowerCase().includes(q)||e.name.lt.toLowerCase().includes(q)||e.muscle.en.toLowerCase().includes(q)).map(e=>{const added=selected.has(e.id);return `<div class="item expick ${added?'added':''}"><button class="exerciseImgBtn" type="button" onclick="openExerciseInfo('${e.id}')">${exerciseImageTag(e,'exerciseMini')}</button><button class="exercisePickBody" type="button" onclick="draftToggleEx('${e.id}')"><b>${esc(e.name[S.lang])}</b><span class="muted">${esc(e.muscle[S.lang])}</span></button><span class="pickMark">${added?'✓': '+'}</span></div>`}).join("")||`<div class="empty">${t("noData")}</div>`}
function planBuilder(mode,id){const editing=mode==='edit';if(editing){const p=S.plans.find(x=>x.id===id);if(!p)return;planDraft={editId:id,name:p.name,exerciseIds:[...p.exerciseIds]}}else{planDraft={editId:null,name:"",exerciseIds:[]}}modal(`<h2>${editing?t("edit"):t("newDay")}</h2><label>${t("name")}</label><input id="planName" value="${esc(planDraft.name)}" placeholder="${S.lang==='lt'?'Krūtinė + tricepsas':'Chest + Triceps'}" oninput="planDraft.name=this.value"><div class="selectedBox"><div class="selectedTitle">${t("selected")}</div><div id="selectedExercises">${planSelectedHtml()}</div></div><label>${t("addFromList")}</label><input id="planSearch" placeholder="${t("search")}" oninput="filterPlanExercises(this.value)"><div id="planPicker" class="list pickList" style="margin-top:10px">${planPickerHtml("")}</div><button class="btn" style="margin-top:14px;width:100%" onclick="savePlanDraft()">${t("save")}</button>`);bindPlanDrag()}
function openPlan(){planBuilder('new')}
function createPlan(){savePlanDraft()}
function editPlan(id){planBuilder('edit',id)}
function refreshPlanBuilder(){const sel=document.getElementById('selectedExercises');if(sel)sel.innerHTML=planSelectedHtml();const q=document.getElementById('planSearch')?.value||'';const list=document.getElementById('planPicker');if(list)list.innerHTML=planPickerHtml(q);bindPlanDrag()}
function filterPlanExercises(q){const list=document.getElementById('planPicker');if(list)list.innerHTML=planPickerHtml(q)}
function draftToggleEx(eid){if(!planDraft)return;if(!planDraft.exerciseIds.includes(eid))planDraft.exerciseIds.push(eid);refreshPlanBuilder()}
function draftRemoveEx(i){if(!planDraft)return;planDraft.exerciseIds.splice(i,1);refreshPlanBuilder()}
function savePlanDraft(){if(!planDraft)return;const n=(document.getElementById('planName')?.value||planDraft.name||'').trim();if(!n)return;if(planDraft.editId){const p=S.plans.find(x=>x.id===planDraft.editId);if(p){p.name=n;p.exerciseIds=[...planDraft.exerciseIds]}}else{S.plans.push({id:uid(),name:n,exerciseIds:[...planDraft.exerciseIds]})}save();planDraft=null;closeModal();show('workouts')}
function movePlanDraft(from,to){if(!planDraft||to<0||to>=planDraft.exerciseIds.length||from===to)return;const a=planDraft.exerciseIds;[a[from],a[to]]=[a[to],a[from]];refreshPlanBuilder()}
function bindPlanDrag(){bindDragList('planDragList',(from,to)=>movePlanDraft(from,to))}
function openExercisePicker(pid){planBuilder('edit',pid)}
function exerciseListHtml(pid,q){return planPickerHtml(q)}
function filterExercises(pid,q){filterPlanExercises(q)}
function addEx(pid,eid){draftToggleEx(eid)}
function removeEx(pid,i){if(planDraft?.editId===pid){draftRemoveEx(i)}else{const p=S.plans.find(x=>x.id===pid);if(p){p.exerciseIds.splice(i,1);save();editPlan(pid)}}}
function moveEx(pid,i,d){if(planDraft?.editId===pid)movePlanDraft(i,i+d)}
function dragSvg(){return '<svg viewBox="0 0 24 24"><path d="M8 5h8M8 12h8M8 19h8"/></svg>'}
function workoutHistoryGroups(){const groups=new Map();S.workouts.forEach(w=>{const gid=w.workoutId||`legacy-${w.date}`;if(!groups.has(gid))groups.set(gid,{id:gid,date:w.date,planId:w.planId||null,planName:w.planName||null,records:[]});groups.get(gid).records.push(w)});return [...groups.values()].sort((a,b)=>b.date.localeCompare(a.date))}
function openWorkoutOverview(gid){const g=workoutHistoryGroups().find(x=>x.id===gid);if(!g)return;modal(`<h2>${esc(g.planName||t("workouts"))}</h2><div class="muted">${t("workoutDate")}: ${g.date}</div><div class="list" style="margin-top:12px">${g.records.map((w,ri)=>{const e=S.exercises.find(x=>x.id===w.exercise);const sets=w.setsData?.length?w.setsData:[{reps:w.reps,weight:w.weight}];return `<div class="card"><b>${esc(e?e.name[S.lang]:w.exercise)}</b><div class="muted" style="margin:5px 0 8px">${e?esc(e.muscle[S.lang]):""}</div>${sets.map((st,i)=>`<div class="row" style="padding:5px 0;border-top:1px solid var(--l)"><span>${i+1}. ${st.reps||0} ${t("reps")}</span><b>${st.weight||0} kg</b></div>`).join("")}</div>`}).join("")}</div><div class="row" style="margin-top:14px"><button class="btn ghost" onclick="closeModal()">${t("back")}</button><button class="btn secondary" onclick="editWorkoutHistory('${esc(g.id)}')">${t("edit")}</button><button class="btn danger" onclick="deleteWorkoutHistory('${esc(g.id)}')">${t("delete")}</button></div>`)}
function editWorkoutHistory(gid){const g=workoutHistoryGroups().find(x=>x.id===gid);if(!g)return;modal(`<h2>${esc(g.planName||t("workouts"))}</h2><div class="muted">${t("workoutDate")}: ${g.date}</div><div class="list" style="margin-top:12px">${g.records.map((w,ri)=>{const e=S.exercises.find(x=>x.id===w.exercise);const sets=w.setsData?.length?JSON.parse(JSON.stringify(w.setsData)):[{reps:w.reps||"",weight:w.weight||""}];return `<div class="card"><b>${esc(e?e.name[S.lang]:w.exercise)}</b>${sets.map((st,i)=>`<div class="setrow"><span>${i+1}</span><input id="hw_${ri}_${i}_r" type="number" value="${st.reps??""}" placeholder="0"><input id="hw_${ri}_${i}_w" type="number" step=".5" value="${st.weight??""}" placeholder="0"><span></span></div>`).join("")}<input type="hidden" id="hw_${ri}_count" value="${sets.length}"><input type="hidden" id="hw_${ri}_id" value="${esc(w.id||"")}"></div>`}).join("")}</div><div class="row" style="margin-top:14px"><button class="btn ghost" onclick="openWorkoutOverview('${esc(g.id)}')">${t("back")}</button><button class="btn" onclick="saveWorkoutHistory('${esc(g.id)}')">${t("save")}</button></div>`)}
function saveWorkoutHistory(gid){const g=workoutHistoryGroups().find(x=>x.id===gid);if(!g)return;g.records.forEach((w,ri)=>{const count=+document.getElementById(`hw_${ri}_count`)?.value||0;const sets=[];for(let j=0;j<count;j++){const reps=document.getElementById(`hw_${ri}_${j}_r`)?.value||"";const weight=document.getElementById(`hw_${ri}_${j}_w`)?.value||"";if(+reps||+weight)sets.push({reps,weight})}w.setsData=sets;w.sets=sets.length;w.reps=Math.max(0,...sets.map(st=>+st.reps||0));w.weight=Math.max(0,...sets.map(st=>+st.weight||0))});save();openWorkoutOverview(gid)}
function deleteWorkoutHistory(gid){if(!confirm(t("confirmDelete")))return;S.workouts=S.workouts.filter(w=>(w.workoutId||`legacy-${w.date}`)!==gid);save();closeModal();show("workouts")}
function workouts(){const hist=workoutHistoryGroups();document.getElementById('workouts').innerHTML=`<h1 class="title">${t("workouts")}</h1><div class="row"><button class="btn" onclick="openPlan()">+ ${t("createDay")}</button>${S.plans.length?`<button class="btn secondary" onclick="choosePlan()">${t("start")}</button>`:""}</div>${S.activeSession?`<div class="card activebox" style="margin-top:12px"><b>${t("start")}: ${esc(S.plans.find(p=>p.id===S.activeSession.planId)?.name||"")}</b><button class="btn" style="margin-top:8px;width:100%" onclick="resumeSession()">${t("start")}</button></div>`:""}<h2 style="margin:20px 0 10px">${t("trainingDays")}</h2><div class="list">${S.plans.map(p=>`<div class="card"><div class="row"><div><h3 style="margin:0">${esc(p.name)}</h3><div class="muted">${p.exerciseIds.length} ${t("exerciseCount")}</div></div><div class="actions"><button class="mini" onclick="editPlan('${p.id}')">${t("edit")}</button><button class="mini danger" onclick="deletePlan('${p.id}')">${t("delete")}</button></div></div><div class="planThumbs">${p.exerciseIds.map(id=>{const e=S.exercises.find(x=>x.id===id);return e?`<button type="button" class="planThumbBtn" onclick="openExerciseInfo('${e.id}')">${exerciseImageTag(e,'exerciseMini')}</button>`:''}).join('')}</div><div class="muted" style="margin-top:8px">${p.exerciseIds.map(id=>{const e=S.exercises.find(x=>x.id===id);return e?esc(e.name[S.lang]):id}).join(" · ")}</div></div>`).join("")||`<div class="empty">${t("noData")}</div>`}</div><h2 style="margin:20px 0 10px">${t("completedWorkouts")}</h2><div class="list">${hist.map(g=>`<div class="item row"><div><b>${esc(g.planName||t("workouts"))}</b><div class="muted">${g.date} · ${g.records.length} ${t("totalExercises")}</div></div><button class="btn secondary" onclick="openWorkoutOverview('${esc(g.id)}')">${t("overview")}</button></div>`).join("")||`<div class="empty">${t("noData")}</div>`}</div><hr><div class="card"><h3>${t("exerciseLibrary")}</h3><input placeholder="${t("search")}" oninput="libraryFilter(this.value)"><div id="libraryList" class="list" style="margin-top:10px;max-height:520px;overflow:auto">${libraryHtml("")}</div></div>`}
function deletePlan(id){if(!confirm(t("confirmDelete")))return;S.plans=S.plans.filter(p=>p.id!==id);if(S.activeSession?.planId===id)S.activeSession=null;save();show("workouts")}
function choosePlan(){modal(`<h2>${t("chooseDay")}</h2><div class="list">${S.plans.map(p=>`<button class="item" onclick="startSession('${p.id}')"><b>${esc(p.name)}</b><span class="muted">${p.exerciseIds.length} ${t("exerciseCount")}</span></button>`).join("")}</div>`)}
function startSession(pid){const p=S.plans.find(x=>x.id===pid);if(!p||!p.exerciseIds.length)return;S.activeSession={planId:pid,date:today(),exercises:p.exerciseIds.map(eid=>({exerciseId:eid,sets:[{reps:"",weight:""},{reps:"",weight:""},{reps:"",weight:""}]}))};save();closeModal();resumeSession()}
function sessionSelectedHtml(){const a=S.activeSession?.exercises||[];if(!a.length)return `<div class="empty">${t("noData")}</div>`;return a.map((x,i)=>{const e=S.exercises.find(z=>z.id===x.exerciseId);return `<div class="dragItem card workout-ex" data-index="${i}" style="margin-top:10px"><div class="workoutTop"><button class="dragHandle" type="button">${dragSvg()}</button>${e?`<button class="exerciseImgBtn" type="button" onclick="openExerciseInfo('${e.id}')">${exerciseImageTag(e,'exerciseMini')}</button>`:''}<button class="exerciseNameBtn" type="button" onclick="openExerciseInfo('${e?.id||x.exerciseId}')"><div style="flex:1;text-align:left"><b>${i+1}. ${esc(e?e.name[S.lang]:x.exerciseId)}</b><div class="muted">${e?esc(e.muscle[S.lang]):""}</div></div></button></div><div class="sethead"><span>#</span><span>${t("reps")}</span><span>${t("kg")}</span><span></span></div>${x.sets.map((set,j)=>`<div class="setrow"><span>${j+1}</span><input type="number" placeholder="0" value="${set.reps}" onchange="sessionSet(${i},${j},'reps',this.value)"><input type="number" step=".5" placeholder="0" value="${set.weight}" onchange="sessionSet(${i},${j},'weight',this.value)"><button class="mini danger" onclick="sessionRemoveSet(${i},${j})">×</button></div>`).join("")}<button class="btn secondary" style="margin-top:8px" onclick="sessionAddSet(${i})">+ ${t("addSet")}</button></div>`}).join('')}
function resumeSession(){const a=S.activeSession;if(!a)return;const p=S.plans.find(x=>x.id===a.planId);modal(`<h2>${esc(p?.name||"")}</h2><div class="muted">${a.date}</div><div class="dragHint" style="margin:10px 0 2px">${t("dragHint")}</div><div id="sessionDragList">${sessionSelectedHtml()}</div><button class="btn secondary sessionAddExerciseBtn" onclick="openSessionExercisePicker()">+ ${t("addExerciseToWorkout")}</button><div class="row" style="margin-top:12px"><button class="btn ghost" onclick="closeModal()">${t("back")}</button><button class="btn" onclick="finishSession()">${t("finish")}</button></div>`);bindSessionDrag()}

function sessionExercisePickerHtml(q){q=(q||"").toLowerCase();const used=new Set((S.activeSession?.exercises||[]).map(x=>x.exerciseId));return S.exercises.filter(e=>!q||e.name.en.toLowerCase().includes(q)||e.name.lt.toLowerCase().includes(q)||e.muscle.en.toLowerCase().includes(q)).map(e=>{const added=used.has(e.id);return `<button class="item expick ${added?'added':''}" type="button" ${added?'disabled':''} onclick="addExerciseToSession('${e.id}')"><b>${esc(e.name[S.lang])}</b><span class="muted">${esc(e.muscle[S.lang])}</span><span class="pickMark">${added?'✓': '+'}</span></button>`}).join("")||`<div class="empty">${t("noData")}</div>`}
function openSessionExercisePicker(){modal(`<h2>${t("addExerciseToWorkout")}</h2><input id="sessionExerciseSearch" placeholder="${t("search")}" oninput="filterSessionExercises(this.value)"><div id="sessionExercisePicker" class="list pickList" style="margin-top:10px">${sessionExercisePickerHtml("")}</div>`)}
function filterSessionExercises(q){const list=document.getElementById('sessionExercisePicker');if(list)list.innerHTML=sessionExercisePickerHtml(q)}
function addExerciseToSession(eid){const a=S.activeSession;if(!a||a.exercises.some(x=>x.exerciseId===eid))return;a.exercises.push({exerciseId:eid,sets:[{reps:"",weight:""},{reps:"",weight:""},{reps:"",weight:""}]});save();resumeSession()}
function bindSessionDrag(){bindDragList('sessionDragList',(from,to)=>{const a=S.activeSession?.exercises;if(!a||to<0||to>=a.length||from===to)return;[a[from],a[to]]=[a[to],a[from]];save();resumeSession()})}
function bindDragList(id,onDrop){const list=document.getElementById(id);if(!list)return;list.querySelectorAll('.dragHandle').forEach(handle=>{let timer=null,dragging=false,startY=0,pointerId=null;const item=handle.closest('.dragItem');const clear=()=>{if(timer)clearTimeout(timer);timer=null};handle.addEventListener('pointerdown',e=>{pointerId=e.pointerId;startY=e.clientY;dragging=false;clear();timer=setTimeout(()=>{dragging=true;item.classList.add('dragging');try{handle.setPointerCapture(pointerId)}catch(_){ }},260)});handle.addEventListener('pointermove',e=>{if(Math.abs(e.clientY-startY)>8&&!dragging)clear();if(dragging)e.preventDefault()});handle.addEventListener('pointerup',e=>{clear();if(!dragging){dragging=false;return}item.classList.remove('dragging');dragging=false;const items=[...list.querySelectorAll('.dragItem')];let to=items.length-1;for(let i=0;i<items.length;i++){if(items[i]===item)continue;const r=items[i].getBoundingClientRect();if(e.clientY<r.top+r.height/2){to=i;break}}const from=Number(item.dataset.index);if(to!==from)onDrop(from,to)});handle.addEventListener('pointercancel',()=>{clear();item.classList.remove('dragging');dragging=false})})}
function sessionSet(i,j,k,v){S.activeSession.exercises[i].sets[j][k]=v;save()}
function sessionAddSet(i){S.activeSession.exercises[i].sets.push({reps:"",weight:""});save();resumeSession()}
function sessionRemoveSet(i,j){if(S.activeSession.exercises[i].sets.length<=1)return;S.activeSession.exercises[i].sets.splice(j,1);save();resumeSession()}
function sessionMove(i,d){const a=S.activeSession.exercises,j=i+d;if(j<0||j>=a.length)return;[a[i],a[j]]=[a[j],a[i]];save();resumeSession()}
function finishSession(){const a=S.activeSession;if(!a)return;const p=S.plans.find(x=>x.id===a.planId);const workoutId=uid();S.workouts.push(...a.exercises.map(x=>({id:uid(),workoutId,planId:a.planId,planName:p?.name||"",date:a.date,exercise:x.exerciseId,sets:x.sets.filter(s=>+s.reps||+s.weight).length,reps:Math.max(0,...x.sets.map(s=>+s.reps||0)),weight:Math.max(0,...x.sets.map(s=>+s.weight||0)),setsData:x.sets.filter(s=>+s.reps||+s.weight)})));S.activeSession=null;save();closeModal();show("workouts")}
function libraryHtml(q){q=(q||"").toLowerCase();return S.exercises.filter(e=>!q||e.name.en.toLowerCase().includes(q)||e.name.lt.toLowerCase().includes(q)||e.muscle.en.toLowerCase().includes(q)).map(e=>`<button type="button" class="item libraryItem" onclick="openExerciseInfo('${e.id}')">${exerciseImageTag(e,'exerciseThumb')}<span class="libraryBody"><b>${esc(e.name[S.lang])}</b><span class="muted">${esc(e.muscle[S.lang])}</span></span><span class="libraryArrow">›</span></button>`).join("")||`<div class="empty">${t("noData")}</div>`}
function libraryFilter(q){document.getElementById("libraryList").innerHTML=libraryHtml(q)}
function exerciseStats(){const m={};S.workouts.forEach(w=>{const vals=(w.setsData?.length?w.setsData:[{weight:w.weight,reps:w.reps}]);const best=Math.max(...vals.map(s=>+s.weight||0));if(!best)return;(m[w.exercise]??=[]).push({date:w.date,weight:best})});return Object.entries(m).map(([id,a])=>{a.sort((x,y)=>x.date.localeCompare(y.date));const first=a[0].weight,latest=a[a.length-1].weight,best=Math.max(...a.map(x=>x.weight));return {id,first,latest,best,pct:first?(latest-first)/first*100:0,date:a.find(x=>x.weight===best)?.date,history:a}})}
function progress(){const es=exerciseStats().sort((a,b)=>b.pct-a.pct);document.getElementById('progress').innerHTML=`<h1 class="title">${t("progress")}</h1><div class="tabs"><button class="tab active" onclick="progressBody()">${t("bodyProgress")}</button><button class="tab" onclick="progressExercises()">${t("exerciseProgress")}</button></div><div id="progressBody"></div>`;progressBody()}
function progressBody(){document.querySelectorAll('.tab').forEach((x,i)=>x.classList.toggle('active',i===0));const p=document.getElementById('progressBody');const measurementCharts=mf.map((k,i)=>{const data=S.measurements.filter(x=>x[k]!==null&&x[k]!==undefined&&x[k]!==0).map(x=>({date:x.date,value:x[k]}));return `<div class="card" style="margin-top:${i?12:0}px"><h3>${t(k)}</h3><canvas id="mc_${k}" width="800" height="250"></canvas></div>`}).join('');p.innerHTML=`<div class="card"><h3>${t("weightTrend")}</h3><canvas id="pc" width="800" height="250"></canvas></div>${measurementCharts||`<div class="empty">${t("noData")}</div>`}`;chart('pc',S.weight);mf.forEach(k=>{const data=S.measurements.filter(x=>x[k]!==null&&x[k]!==undefined&&x[k]!==0).map(x=>({date:x.date,value:x[k]}));chart('mc_'+k,data)})}
function progressExercises(){document.querySelectorAll('.tab').forEach((x,i)=>x.classList.toggle('active',i===1));const es=exerciseStats().sort((a,b)=>b.pct-a.pct);document.getElementById('progressBody').innerHTML=`<div class="list">${es.map(x=>{const e=S.exercises.find(z=>z.id===x.id),p=x.pct;return `<div class="card"><div class="row"><div><b>${esc(e?e.name[S.lang]:x.id)}</b><div class="muted">${e?esc(e.muscle[S.lang]):""}</div></div><strong class="pct ${p>=0?'up':'down'}">${p>=0?'+':''}${p.toFixed(1)}%</strong></div><div class="statgrid"><div><span class="muted">${t("first")}</span><b>${x.first} kg</b></div><div><span class="muted">${t("latest")}</span><b>${x.latest} kg</b></div><div><span class="muted">${t("pr")}</span><b>${x.best} kg</b><small>${x.date||""}</small></div></div><canvas id="ec_${x.id}" width="800" height="130"></canvas></div>`}).join("")||`<div class="empty">${t("noData")}</div>`}</div>`;es.forEach(x=>chart('ec_'+x.id,x.history))}
function chart(id,a){let c=document.getElementById(id);if(!c)return;let x=c.getContext('2d'),w=c.width,h=c.height;x.clearRect(0,0,w,h);x.font='12px -apple-system,BlinkMacSystemFont,Segoe UI,Arial,sans-serif';x.textAlign='center';x.strokeStyle="#e4e7ec";for(let i=0;i<4;i++){let y=25+i*(h-55)/3;x.beginPath();x.moveTo(42,y);x.lineTo(w-18,y);x.stroke()}if(!a.length){x.fillStyle="#667085";x.fillText(t("noData"),w/2,h/2);return}const clean=a.map(z=>({value:+(z.value??z.weight)||0,date:z.date||''})).filter(z=>Number.isFinite(z.value));let v=clean.map(z=>z.value),mn=Math.min(...v),mx=Math.max(...v);if(mn===mx){const pad=Math.max(1,mn*0.05);mn-=pad;mx+=pad}const left=42,right=18,top=25,bottom=35,span=Math.max(1,clean.length-1);const pts=clean.map((z,i)=>{const px=left+i*(w-left-right)/span;const py=top+(mx-z.value)/(mx-mn)*(h-top-bottom);return {...z,px,py}});x.strokeStyle="#2563eb";x.lineWidth=3;x.lineJoin='round';x.beginPath();pts.forEach((p,i)=>i?x.lineTo(p.px,p.py):x.moveTo(p.px,p.py));x.stroke();pts.forEach((p,i)=>{x.fillStyle="#fff";x.strokeStyle="#2563eb";x.lineWidth=3;x.beginPath();x.arc(p.px,p.py,5,0,Math.PI*2);x.fill();x.stroke();x.fillStyle="#101828";x.font='bold 12px -apple-system,BlinkMacSystemFont,Segoe UI,Arial,sans-serif';x.fillText(`${p.value}`,p.px,Math.max(14,p.py-10));if(p.date){x.fillStyle="#667085";x.font='10px -apple-system,BlinkMacSystemFont,Segoe UI,Arial,sans-serif';const d=p.date.slice(5)||p.date;x.fillText(d,p.px,h-10)}})}
function photos(){document.getElementById('photos').innerHTML=`<h1 class="title">${t("photosTitle")}</h1><div class="card"><label>${t("upload")}</label><input type="file" accept="image/*" multiple onchange="addPhotos(this)"></div><div class="photo-grid" style="margin-top:12px">${S.photos.map((p,i)=>`<div><img src="${p.data}"><div class="muted" style="text-align:center;margin:6px 0 8px">${esc(p.date||"")}</div><button class="btn danger" style="width:100%" onclick="deletePhoto(${i})">${t("delete")}</button></div>`).join("")||`<div class="empty" style="grid-column:1/-1">${t("noData")}</div>`}</div>`}
function deletePhoto(i){if(!confirm(t("confirmDelete")))return;S.photos.splice(i,1);save();photos()}
function addPhotos(i){[...i.files].forEach(f=>{let r=new FileReader;r.onload=()=>{S.photos.push({date:today(),data:r.result});save();photos()};r.readAsDataURL(f)})}
function nutrition(){document.getElementById('nutrition').innerHTML=`<h1 class="title">${t("nutrition")}</h1><button class="btn" onclick="openN()">+ ${t("addNutrition")}</button><div class="list" style="margin-top:12px">${S.nutrition.map((x,i)=>({x,i})).reverse().map(o=>`<div class="item"><div class="row"><b>${o.x.calories} kcal</b><div class="actions"><button class="mini" onclick="openN(${o.i})">${t("edit")}</button><button class="mini danger" onclick="deleteNutrition(${o.i})">${t("delete")}</button></div></div><div class="muted" style="margin-top:6px">${o.x.date} · P ${o.x.protein} · C ${o.x.carbs} · F ${o.x.fat}</div></div>`).join("")||`<div class="empty">${t("noData")}</div>`}</div>`}
function openN(index=null){const x=index!==null?S.nutrition[index]:null;modal(`<h2>${x?t("edit"):t("addNutrition")}</h2><label>${t("date")}</label><input id="nd" type="date" value="${x?.date||today()}"><div class="formgrid"><div><label>${t("calories")}</label><input id="nc" type="number" value="${x?.calories??""}"></div><div><label>${t("protein")}</label><input id="np" type="number" value="${x?.protein??""}"></div><div><label>${t("carbs")}</label><input id="ncarb" type="number" value="${x?.carbs??""}"></div><div><label>${t("fat")}</label><input id="nf" type="number" value="${x?.fat??""}"></div></div><div class="row" style="margin-top:12px"><button class="btn ghost" onclick="closeModal()">${t("cancel")}</button><button class="btn" onclick="saveN(${index===null?'null':index})">${t("save")}</button></div>`)}
function saveN(index){const o={id:index!==null&&S.nutrition[index]?.id||uid(),date:document.getElementById('nd').value,calories:+document.getElementById('nc').value||0,protein:+document.getElementById('np').value||0,carbs:+document.getElementById('ncarb').value||0,fat:+document.getElementById('nf').value||0};if(index===null)S.nutrition.push(o);else S.nutrition[index]=o;save();closeModal();show('nutrition')}
function deleteNutrition(i){if(!confirm(t("confirmDelete")))return;S.nutrition.splice(i,1);save();show('nutrition')}
function goals(){document.getElementById('goals').innerHTML=`<h1 class="title">${t("goalsTitle")}</h1><button class="btn" onclick="openGoal()">+ ${t("addGoal")}</button><div class="list" style="margin-top:12px">${S.goals.map((x,i)=>`<div class="item row"><span><b>${esc(x.type)}</b><div class="muted">${esc(x.value)}</div></span><div class="actions"><button class="mini secondary" onclick="S.goals[${i}].done=!S.goals[${i}].done;save();goals()">${x.done?t("complete"):t("active")}</button><button class="mini" onclick="openGoal(${i})">${t("edit")}</button><button class="mini danger" onclick="deleteGoal(${i})">${t("delete")}</button></div></div>`).join("")||`<div class="empty">${t("noData")}</div>`}</div>`}
function openGoal(index=null){const x=index!==null?S.goals[index]:null;modal(`<h2>${x?t("edit"):t("addGoal")}</h2><label>${t("goalType")}</label><input id="gt" value="${esc(x?.type||"")}"><label>${t("targetValue")}</label><input id="gv" value="${esc(x?.value||"")}"><div class="row" style="margin-top:12px"><button class="btn ghost" onclick="closeModal()">${t("cancel")}</button><button class="btn" onclick="saveGoal(${index===null?'null':index})">${t("save")}</button></div>`)}
function saveGoal(index){const o={id:index!==null&&S.goals[index]?.id||uid(),type:document.getElementById('gt').value.trim(),value:document.getElementById('gv').value.trim(),done:index!==null?!!S.goals[index].done:false};if(!o.type&&!o.value)return;if(index===null)S.goals.push(o);else S.goals[index]=o;save();closeModal();show('goals')}
function deleteGoal(i){if(!confirm(t("confirmDelete")))return;S.goals.splice(i,1);save();show('goals')}
function more(){document.getElementById('more').innerHTML=`<h1 class="title">${t("moreTitle")}</h1><div class="list"><button class="item" onclick="show('weight')">⚖️ ${t("weight")}</button><button class="item" onclick="show('measurements')">📏 ${t("measurements")}</button><button class="item" onclick="show('nutrition')">🥗 ${t("nutrition")}</button><button class="item" onclick="show('goals')">🎯 ${t("goals")}</button><button class="item" onclick="show('settings')">⚙️ ${t("settings")}</button></div>`}
function settings(){document.getElementById('settings').innerHTML=`<h1 class="title">${t("settings")}</h1><div class="card"><h3>${t("language")}</h3><select onchange="setLang(this.value)"><option value="en" ${S.lang==='en'?'selected':''}>${t("english")}</option><option value="lt" ${S.lang==='lt'?'selected':''}>${t("lithuanian")}</option></select></div><div class="card" style="margin-top:12px"><button class="btn secondary" onclick="exportData()">${t("backup")}</button><label class="btn secondary" style="text-align:center;margin-top:8px">${t("restore")}<input type="file" accept=".json" style="display:none" onchange="importData(this)"></label><button class="btn danger" style="margin-top:8px" onclick="clearData()">${t("clear")}</button></div>`}
function setLang(v){const current=document.querySelector('.view.active')?.id||'dashboard';S.lang=v;save();nav();document.getElementById("langBtn").textContent=v==='en'?'LT':'EN';show(current)}
function exportData(){let a=document.createElement('a'),b=new Blob([JSON.stringify(S)],{type:'application/json'});a.href=URL.createObjectURL(b);a.download='asfitness-backup.json';a.click()}
function importData(i){let r=new FileReader;r.onload=()=>{try{S=JSON.parse(r.result);save();location.reload()}catch(e){alert('Invalid backup')}};r.readAsText(i.files[0])}
function clearData(){if(confirm(t('confirmClear'))){S=structuredClone(D);S.lang='en';save();location.reload()}}
document.getElementById('langBtn').onclick=()=>setLang(S.lang==='en'?'lt':'en');nav();renderDrawer();document.getElementById('langBtn').textContent=S.lang==='en'?'LT':'EN';dashboard();if('serviceWorker'in navigator)navigator.serviceWorker.register('sw.js').catch(()=>{});
